  let out = '', err = '';
  cp.stdout.on('data', d => out += d);
  cp.stderr.on('data', d => err += d);
  cp.on('close', code => {
    console.error('EXIT ' + code);
    console.error('OUT_LEN ' + out.length);
    console.error('OUT_HEAD ' + JSON.stringify(out.slice(0, 600)));
    console.error('ERR_TAIL ' + JSON.stringify(err.split('\n').filter(l => /CONSOLE|ERROR|Uncaught/.test(l)).slice(-10).join('\n')));
    server.close();
  });
});
