// Temporary smoke check: serve the repo over HTTP, load demo.html in headless
// chromium, assert every board rendered, save a screenshot.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { resolve, extname } from 'node:path';
import { spawn } from 'node:child_process';

const root = process.argv[2];
const chrome = process.argv[3];
const shotPath = process.argv[4];
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json' };

const server = createServer(async (req, res) => {
  try {
    let p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    if (p === '/') p = '/demo.html';
    const file = resolve(root, '.' + p);
    if (!file.startsWith(root)) { res.writeHead(403); res.end(); return; }
    const data = await readFile(file);
    res.writeHead(200, { 'content-type': types[extname(file)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('not found');
  }
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const url = 'http://127.0.0.1:' + server.address().port + '/demo.html';

const run = (args) =>
  new Promise((res2) => {
    const cp = spawn(chrome, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    cp.stdout.on('data', (d) => (out += d));
const base = ['--headless', '--no-sandbox', '--disable-gpu'];
    const kill = setTimeout(() => cp.kill(), 30000);
    cp.on('close', (code) => {
      clearTimeout(kill);
      res2({ code, out, err });
    });
  });

const base = ['--headless', '--no-sandbox', '--disable-gpu', '--virtual-time-budget=4000'];
const domRun = await run([...base, '--enable-logging=stderr', '--dump-dom', url]);
const shotRun = await run([...base, '--window-size=1500,950', '--screenshot=' + shotPath, url]);
server.close();

