  const m = rest.slice(1).search(/id="board-\d+|<\/body>/);
  return m === -1 ? rest : rest.slice(0, m + 1);
};
const boards = {};
for (const id of ['board-1', 'board-2', 'board-3', 'board-4', 'board-5']) {
  const b = sliceBoard(domRun.out, id);
  boards[id] = {
    squares: count(b, /<square[\s>]/g),
    pieces: count(b, /<piece[\s>]/g),
  };
}
