const consoleErrors = domRun.err
  .split('\n')
  .filter((l) => /CONSOLE.*(error|Uncaught)|Uncaught/.test(l));

const expected = { 'board-1': 32, 'board-2': 19, 'board-3': 32, 'board-4': 32, 'board-5': 32 };
const failures = [];
if (domRun.code !== 0) failures.push('dump-dom exited ' + domRun.code);
if (shapeSvgs.length !== 1) failures.push('expected 1 cg-shapes svg, got ' + shapeSvgs.length);
if (shapePaths !== 7) failures.push('expected 7 shape paths, got ' + shapePaths);
for (const [id, pieces] of Object.entries(expected)) {
